-- Report ID : RPT_069
-- Report    : Pack Item Supplier Pack Size Repl
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,      im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      im.ITEM                                               AS pack_item_id,     im.ITEM_DESC                                          AS pack_item_desc,     im.PACK_IND                                           AS pack_ind,     im.STANDARD_UOM                                       AS pack_uom,     im.STATUS                                             AS item_status,      pi.ITEM                                               AS component_item_id,     cim.ITEM_DESC                                         AS component_item_desc,     pi.PACK_QTY                                           AS component_qty_in_pack,     cim.STANDARD_UOM                                      AS component_uom,      ril.LOCATION                                          AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS item_loc_status_desc,      isc.SUPPLIER                                          AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,     isc.ORIGIN_COUNTRY_ID                                 AS origin_country,     isc.PRIMARY_SUPP_IND                                  AS primary_supp_ind,     isc.PRIMARY_COUNTRY_IND                               AS primary_country_ind,      isc.SUPP_PACK_SIZE                                    AS supp_pack_size,     isc.INNER_PACK_SIZE                                   AS inner_pack_size,     isc.TI                                                AS pallet_tier,     isc.HI                                                AS pallet_high,     (isc.TI * isc.HI * isc.SUPP_PACK_SIZE)               AS pallet_order_multiple,      CASE         WHEN isc.SUPP_PACK_SIZE BETWEEN 2  AND 5   THEN '2 - 5 Cases'         WHEN isc.SUPP_PACK_SIZE BETWEEN 6  AND 12  THEN '6 - 12 Cases'         WHEN isc.SUPP_PACK_SIZE BETWEEN 13 AND 24  THEN '13 - 24 Cases'         WHEN isc.SUPP_PACK_SIZE > 24               THEN '25+ Cases'         ELSE 'Review'     END                                                   AS pack_size_bucket,      'USING GLOBAL DEFAULT'                                AS pack_size_override_status,      isc.SUPP_PACK_SIZE                                    AS effective_supp_pack_size,     isc.INNER_PACK_SIZE                                   AS effective_inner_pack_size,      isc.UNIT_COST                                         AS unit_cost,     ROUND(isc.UNIT_COST * isc.SUPP_PACK_SIZE, 4)         AS pack_total_cost,     isc.PICKUP_LEAD_TIME                                  AS pickup_lead_time,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS stock_category_desc,     ril.REPL_ORDER_CTRL                                   AS order_control,     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'         ELSE ril.REPL_ORDER_CTRL     END                                                   AS order_control_desc,     ril.MIN_STOCK                                         AS min_stock,     ril.MAX_STOCK                                         AS max_stock,     ril.REVIEW_CYCLE                                      AS review_cycle,     ril.SOURCE_WH                                         AS source_warehouse,     ril.PRIMARY_PACK_NO                                   AS primary_repl_pack,     ril.NON_SCALING_IND                                   AS scaling_exempt_ind,     ril.MAX_SCALE_VALUE                                   AS max_scale_amount,      ils.STOCK_ON_HAND                                     AS pack_current_soh,     ils.AV_COST                                           AS pack_wac,      il.SELLING_UNIT_RETAIL                                AS pack_unit_retail,      cils.STOCK_ON_HAND                                    AS component_current_soh,      CASE         WHEN NVL(ril.MAX_STOCK, 0) > 0              AND NVL(ils.STOCK_ON_HAND, 0) < ril.MAX_STOCK         THEN CEIL(              (ril.MAX_STOCK - NVL(ils.STOCK_ON_HAND, 0))              / isc.SUPP_PACK_SIZE              ) * isc.SUPP_PACK_SIZE         ELSE 0     END                                                   AS estimated_order_qty,      CASE         WHEN im.PACK_IND = 'Y'              AND isc.SUPP_PACK_SIZE > 1         THEN 'REVIEW: Catch Weight WP recommends SUPP_PACK_SIZE=1 for simple packs'         ELSE 'MONITOR'     END                                                   AS recommendation  FROM     MFCS_RDS.RDS_WV_ITEM_MASTER             im      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  im.ITEM              = isc.ITEM                                                   AND  isc.PRIMARY_SUPP_IND = 'Y'                                                   AND  isc.PRIMARY_COUNTRY_IND = 'Y'                                                   AND  isc.SUPP_PACK_SIZE   > 1      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC     ril  ON  im.ITEM              = ril.ITEM                                                   AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                   AND  ril.REPL_METHOD    IS NOT NULL      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC           il  ON  ril.ITEM             = il.ITEM                                                   AND  ril.LOCATION        = il.LOC                                                   AND  il.LOC_TYPE         = ril.LOC_TYPE      JOIN  MFCS_RDS.RDS_WV_DEPS               d   ON  im.DEPT              = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS              c   ON  im.DEPT              = c.DEPT                                                   AND  im.CLASS             = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc  ON  im.DEPT              = sc.DEPT                                                   AND  im.CLASS             = sc.CLASS                                                   AND  im.SUBCLASS          = sc.SUBCLASS       LEFT JOIN MFCS_RDS.RDS_WV_PACKITEM       pi  ON  im.ITEM              = pi.PACK_NO      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_MASTER    cim ON  pi.ITEM              = cim.ITEM      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                   ON  im.ITEM              = iscl.ITEM                                                   AND  isc.SUPPLIER        = iscl.SUPPLIER                                                   AND  iscl.LOC            = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS           sp  ON  isc.SUPPLIER         = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE          st  ON  ril.LOCATION         = st.STORE                                                   AND  il.LOC_TYPE          = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH             wh  ON  ril.LOCATION         = wh.WH                                                   AND  il.LOC_TYPE          = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  ils  ON  im.ITEM              = ils.ITEM                                                   AND  ril.LOCATION        = ils.LOC                                                   AND  ils.LOC_TYPE        = ril.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils ON  pi.ITEM              = cils.ITEM                                                   AND  ril.LOCATION        = cils.LOC                                                   AND  cils.LOC_TYPE       = ril.LOC_TYPE  WHERE     im.PACK_IND          = 'Y'     AND isc.SUPP_PACK_SIZE > 1     AND ril.REPL_METHOD  IS NOT NULL     AND il.STATUS        IN ('A', 'C')     AND im.STATUS         = 'A'  ORDER BY     isc.SUPP_PACK_SIZE   DESC,     d.DEPT_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END